import java.util.concurrent.*;

public class ConcurrencyDemo {
    public static void main(String[] args) throws InterruptedException {
        int parties = 3;
        CountDownLatch latch = new CountDownLatch(parties);
        CyclicBarrier barrier = new CyclicBarrier(parties, () -> System.out.println("Barrier tripped! Next phase."));
        Semaphore semaphore = new Semaphore(2);
        Exchanger<String> exchanger = new Exchanger<>();
        Phaser phaser = new Phaser(1); // Register self

        ExecutorService executor = Executors.newFixedThreadPool(parties);
        for (int i = 0; i < parties; i++) {
            final int id = i;
            executor.submit(() -> {
                try {
                    semaphore.acquire();
                    System.out.println("Worker " + id + " acquired permit.");

                    latch.countDown();
                    barrier.await();

                    if (id == 0) {
                        String exchanged = exchanger.exchange("Data from 0");
                        System.out.println("Worker 0 got: " + exchanged);
                    }
                } catch (Exception e) {
                    Thread.currentThread().interrupt();
                } finally {
                    semaphore.release();
                }
            });
        }
        latch.await();
        executor.shutdown();
    }
}
